//! 🧾️ An original typed value supplies a bounded independent metadata owner per declared recipient.
use semio_framework_value::retained_clone::RetainedClone;
use semio_framework_job::{OriginalConstructionDemand,OriginalSourceBinding,OriginalTurnFailure,StepContext,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneOwner,RetainedCloneClose}};
use std::{collections::VecDeque,mem::{ManuallyDrop,size_of}};
fn built<O>(cx:&mut semio_framework_job::StepContext<'_>,output:&mut Option<O>,demand:semio_framework_job::OriginalConstructionDemand,construct:impl FnOnce()->Result<(O,semio_framework_value::RetainedCloneProgress),semio_framework_value::ValueError>)->Result<bool,semio_framework_job::OriginalTurnFailure>{semio_framework_job::admit_original_construction(cx,output,demand,|_|semio_framework_value::RetainedWorkOutcome{result:construct(),work:1})}
fn built_with<O>(cx:&mut semio_framework_job::StepContext<'_>,output:&mut Option<O>,demand:semio_framework_job::OriginalConstructionDemand,construct:impl FnOnce(&mut semio_framework_value::NativeDecodeControl<'_>)->Result<(O,semio_framework_value::RetainedCloneProgress),semio_framework_value::ValueError>)->Result<bool,semio_framework_job::OriginalTurnFailure>{semio_framework_job::admit_original_construction(cx,output,demand,|control|semio_framework_value::RetainedWorkOutcome{result:construct(control),work:1})}
fn retired(cx:&mut semio_framework_job::StepContext<'_>,demand:semio_framework_value::RetirementDemand,advance:impl FnOnce(semio_framework_value::RetainedCloneGrant)->Result<semio_framework_value::RetainedCloneStep,semio_framework_value::ValueError>)->Result<semio_framework_job::InteractiveJobCloseStep,semio_framework_job::OriginalTurnFailure>{semio_framework_job::close_original_retained_step(cx,demand,|grant|semio_framework_value::RetainedWorkOutcome{result:advance(grant),work:1})}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original typed metadata copies source changed")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
/// 🪡️ Each resulting origin owns its actual bounded text copies and preserves the complete original metadata.
pub struct OriginalValueCopies<T:RetainedClone>{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,total:usize,original:ManuallyDrop<Option<T>>,source:ManuallyDrop<Option<RetainedCloneSource<T>>>,admission:Option<semio_framework_value::retained_clone::RetainedCloneSourceAdmission<T,T,()>>,cursor:ManuallyDrop<Option<RetainedCloneOwner<T>>>,values:ManuallyDrop<Option<VecDeque<T>>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl<T:RetainedClone> OriginalValueCopies<T>{
 pub fn admit(original:&mut Option<T>,count:usize,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if original.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};built_with(cx,output,construction(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,total:count,original:ManuallyDrop::new(original.take()),source:ManuallyDrop::new(None),admission:None,cursor:ManuallyDrop::new(None),values:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}),receipt(d))))}
 fn next_phase(&mut self,phase:u8,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=fixed::<u8>();let mut done=None;built(cx,&mut done,construction(d),||{self.phase=phase;Ok(((),receipt(d)))})?;Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original typed metadata copies was cancelled").into())}if cx.should_yield(){return Ok(false)}match self.phase{
  0=>{if self.admission.is_none(){self.admission=Some(RetainedCloneSource::admission_owned(self.original.take().ok_or_else(invalid)?,()));}let admission=self.admission.as_ref().unwrap();let d=if admission.phase()=="ready"{fixed::<Option<RetainedCloneSource<T>>>()}else{admission.next_demand()?};let grant=cx.retained_grant();let mut done=None;built(cx,&mut done,construction(d),||{let admission=self.admission.as_mut().unwrap();if admission.phase()!="ready"{let step=admission.advance(grant).result?;return Ok(((),step.progress()))}let mut output=None;let step=admission.take_output(&mut output,grant).result?;if output.is_some(){*self.source=output;self.admission=None;}Ok(((),step.progress()))})?;if self.source.is_some(){self.phase=1}},
  1=>{let d=RetirementDemand{capacity_bytes:self.total.checked_mul(size_of::<T>()).ok_or_else(invalid)?,..fixed::<VecDeque<T>>()};built(cx,&mut self.values,construction(d),||{let mut values=VecDeque::new();values.try_reserve_exact(self.total).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original typed metadata copies rows could not be reserved"))?;let mut p=receipt(d);p.retained_capacity_bytes=values.capacity()*size_of::<T>();Ok((values,p))})?;if self.values.is_some(){self.phase=2}},
  2=>{if self.values.as_ref().unwrap().len()==self.total{self.next_phase(6,cx)?;return Ok(false)}let d=fixed::<RetainedCloneOwner<T>>();built(cx,&mut self.cursor,construction(d),||Ok((RetainedCloneOwner::default(),receipt(d))))?;if self.cursor.is_some(){self.phase=3}},
  3=>{let source=self.source.as_ref().unwrap().try_borrow()?;let cursor=self.cursor.as_mut().unwrap();let d=cursor.advance_demands(source,self.body)?;let grant=cx.retained_grant();let mut done=None;built(cx,&mut done,construction(d),||{let step=cursor.advance(source,self.body,grant).result?;if matches!(step,RetainedCloneStep::Complete(_)){self.phase=4}Ok(((),step.progress()))})?;},
  4=>{let d=fixed::<(T,usize)>();let mut done=None;let grant=cx.retained_grant();built(cx,&mut done,construction(d),||{let value=self.cursor.as_mut().unwrap().take(grant).result?.map(|(value,_)|value).ok_or_else(invalid)?;self.values.as_mut().unwrap().push_back(value);self.phase=5;Ok(((),receipt(d)))})?;},
  5=>{if self.close_cursor(cx)?{self.next_phase(2,cx)?}},
  6=>{if self.close_source(cx)?{self.next_phase(7,cx)?}},
  7=>return Ok(true),_=>unreachable!(),
 }Ok(self.phase==7)}
 fn close_cursor(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(cursor)=self.cursor.as_mut()else{return Ok(true)};if !cursor.terminal_is_empty(){let d=cursor.selected_close_demand(self.body)?;retired(cx,d,|grant|cursor.close_step(grant).result)?;return Ok(false)}let d=fixed::<Option<RetainedCloneOwner<T>>>();retired(cx,d,|_|{self.cursor.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(false)}
 fn close_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(admission)=self.admission.as_ref(){let d=if admission.phase()=="ready"{fixed::<Option<RetainedCloneSource<T>>>()}else{admission.next_return_demand()?};retired(cx,d,|grant|{let admission=self.admission.as_mut().unwrap();if admission.phase()=="ready"{let mut output=None;let step=admission.take_output(&mut output,grant).result?;if output.is_some(){*self.source=output;self.admission=None;}return Ok(RetainedCloneStep::Progress(step.progress()))}let mut back=None;let step=admission.return_inputs(&mut back,grant).result?;if let Some((value,()))=back{*self.original=Some(value);self.admission=None;}Ok(RetainedCloneStep::Progress(step.progress()))})?;return Ok(false)}let Some(source)=self.source.as_mut()else{return Ok(true)};if !source.terminal_is_empty(){let d=source.next_close_demand(self.body)?;retired(cx,d,|grant|source.close_step(grant).result)?;return Ok(false)}let d=fixed::<Option<RetainedCloneSource<T>>>();retired(cx,d,|_|{self.source.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(false)}
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<VecDeque<T>>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=7||self.closing||self.values.is_none(){return Err(invalid().into())}let d=fixed::<(Option<VecDeque<T>>,Option<VecDeque<T>>)>();built(cx,output,construction(d),||Ok((self.values.take().unwrap(),receipt(d))))}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.closing=true;if !self.close_cursor(cx)?||!self.close_source(cx)?{return Ok(false)}if self.original.is_some(){let d=self.retirement.next_owner_demands::<T>(true,&None,self.body)?;retired(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.original,grant).result?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}if !self.retirement.is_empty(){let selection=self.retirement.select(self.body)?;let d=selection.demands();retired(cx,d,|grant|selection.step(grant).result)?;return Ok(false)}if self.values.is_some(){let d=self.retirement.next_owner_demands::<VecDeque<T>>(true,&None,self.body)?;retired(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.values,grant).result?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.original.is_none()&&self.admission.is_none()&&self.source.is_none()&&self.cursor.is_none()&&self.values.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<T:RetainedClone> Drop for OriginalValueCopies<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original typed metadata copies requires funded closure")}}

